-- ============================================================================
-- SOURCE TABLE: EquipmentRegistry
-- ============================================================================
-- Factory credentials and equipment metadata from packing lists.
--
-- Two source files merged:
--   1. data/teltonika-NET-071664 imei.xlsx  (Teltonika factory packing list)
--   2. data/equipment_registration_v2.xlsx  (Ops equipment registration)
--
-- Generated by ImportEquipmentRegistration.py
-- ============================================================================

SET ROLE db_sleetmigration_owner;

-- Part 1: Teltonika factory packing list (serial → password/IMEI/MAC)
DROP TABLE IF EXISTS "Source"."TeltonikaPackingList" CASCADE;

CREATE TABLE "Source"."TeltonikaPackingList" (
    serial TEXT PRIMARY KEY,
    device_type TEXT NOT NULL,      -- RUT956 or TSW212
    imei TEXT,
    mac TEXT,                       -- Factory MAC (colon-separated)
    firmware_version TEXT,
    wifi_password TEXT,             -- Only for RUT devices
    device_password TEXT             -- Factory default password
);

-- 100 devices from Teltonika packing list



-- Part 2: Equipment registration (router_id → location, serial, SIM, meter)
DROP TABLE IF EXISTS "Source"."EquipmentRegistration" CASCADE;

CREATE TABLE "Source"."EquipmentRegistration" (
    router_id TEXT PRIMARY KEY,
    location_name TEXT,
    serial TEXT,                    -- Router serial number
    lan_mac TEXT,                   -- LAN MAC address (colon-separated)
    device_password TEXT,           -- Factory default password from Ops records
    energic TEXT,                   -- Energy meter info (ProductId;Manufacturer;Ser.no)
    meter_id TEXT,                  -- Meter ID reference (e.g. W047101-M1)
    powersupply TEXT,               -- Power supply serial
    coils TEXT,                     -- Current transformer model
    iccid TEXT,                     -- SIM card ICCID
    fuse_size INTEGER,              -- Fuse size (A)
    wattif_installer TEXT            -- Installer company/person
);

-- 186 entries from equipment registration



